//! Benchmark / smoke-test client for the aegis-infer gRPC server.
//!
//! ## Usage
//!
//! ```bash
//! # Start server first (mock mode):
//! cargo run --bin aegis-infer -- --mock --log-level warn
//!
//! # In another terminal:
//! cargo run --bin infer-bench -- --requests 10000 --concurrency 200
//!
//! # Against a UDS socket:
//! cargo run --bin infer-bench -- --endpoint unix:///tmp/aegis-infer.sock
//! ```

use std::sync::Arc;
use std::time::{Duration, Instant};

use clap::Parser;
use tokio::task::JoinSet;
use tonic::transport::{Channel, Endpoint};

// Include proto types (generated by tonic-build).
mod proto {
    tonic::include_proto!("aegis.infer.v1");
}
use proto::{aegis_infer_client::AegisInferClient, ClassifyRequest, HealthRequest, StatsRequest};

// ── CLI ───────────────────────────────────────────────────────────────────────

#[derive(Parser, Debug)]
#[command(name = "infer-bench", about = "Aegis inference server benchmark client")]
struct Args {
    /// Server endpoint.
    ///   TCP:  host:port  (e.g. 127.0.0.1:50051)
    ///   UDS:  unix:///path/to/socket
    #[arg(long, default_value = "127.0.0.1:50051")]
    endpoint: String,

    /// Total number of Classify RPC calls to send.
    #[arg(long, default_value = "10000")]
    requests: usize,

    /// Max concurrent outstanding RPCs.
    #[arg(long, default_value = "200")]
    concurrency: usize,

    /// Payload type: "clean" | "attack" | "mixed"
    #[arg(long, default_value = "mixed")]
    payload: String,

    /// Warm-up requests (excluded from latency stats).
    #[arg(long, default_value = "500")]
    warmup: usize,

    /// Print a progress line every N completed requests.
    #[arg(long, default_value = "2000")]
    print_every: usize,
}

// ── Sample payloads ───────────────────────────────────────────────────────────

fn sample_requests(payload: &str, n: usize) -> Vec<String> {
    let clean = [
        "GET /api/users?id=42",
        "POST /api/login user=alice&pass=s3cr3t",
        "GET /health",
        "GET /dashboard?tab=overview&page=1",
        "POST /api/order amount=99.99&currency=USD",
        "GET /static/app.js",
        "GET /api/products?category=electronics&limit=20",
        "PUT /api/profile name=Bob&email=bob@example.com",
    ];
    let attack = [
        "GET /search?q=' UNION SELECT username,password FROM users--",
        "POST /login user=admin'--&pass=x",
        "GET /files?path=../../../../etc/passwd",
        "GET /api?url=http://169.254.169.254/latest/meta-data/",
        "GET /ping?host=8.8.8.8;cat /etc/shadow",
        "GET /admin\nUser-Agent: sqlmap/1.7",
        "GET /search?q=<script>alert(document.cookie)</script>",
        "GET /template?t={{7*7}}",
    ];

    (0..n)
        .map(|i| {
            let pool = match payload {
                "clean"  => &clean[..],
                "attack" => &attack[..],
                _        => if i % 2 == 0 { &clean[..] } else { &attack[..] },
            };
            pool[i % pool.len()].to_string()
        })
        .collect()
}

// ── Channel builder ───────────────────────────────────────────────────────────

async fn build_channel(endpoint_str: &str) -> anyhow::Result<Channel> {
    if endpoint_str.starts_with("unix://") {
        // Unix domain socket
        use hyper_util::rt::TokioIo;
        use tokio::net::UnixStream;
        use tower::service_fn;

        let path = endpoint_str.trim_start_matches("unix://").to_string();
        let channel = Endpoint::from_static("http://[::]:0")
            .connect_with_connector(service_fn(move |_| {
                let p = path.clone();
                async move {
                    let stream = UnixStream::connect(p).await?;
                    Ok::<_, std::io::Error>(TokioIo::new(stream))
                }
            }))
            .await?;
        Ok(channel)
    } else {
        // TCP
        let url = if endpoint_str.starts_with("http") {
            endpoint_str.to_string()
        } else {
            format!("http://{endpoint_str}")
        };
        let channel = Endpoint::from_shared(url)?.connect().await?;
        Ok(channel)
    }
}

// ── Latency percentiles ───────────────────────────────────────────────────────

fn percentile(sorted: &[f64], p: f64) -> f64 {
    if sorted.is_empty() { return 0.0; }
    let idx = ((sorted.len() as f64 * p / 100.0).ceil() as usize).min(sorted.len()) - 1;
    sorted[idx]
}

// ── Main ─────────────────────────────────────────────────────────────────────

#[tokio::main]
async fn main() -> anyhow::Result<()> {
    let args = Args::parse();

    println!("╔══════════════════════════════════════════════════════╗");
    println!("║         Aegis Inference Server — Benchmark           ║");
    println!("╠══════════════════════════════════════════════════════╣");
    println!("║  endpoint    : {:<36}  ║", args.endpoint);
    println!("║  requests    : {:<36}  ║", args.requests);
    println!("║  concurrency : {:<36}  ║", args.concurrency);
    println!("║  payload     : {:<36}  ║", args.payload);
    println!("╚══════════════════════════════════════════════════════╝");

    // ── Connect ───────────────────────────────────────────────────────────────
    print!("\nConnecting to {} … ", args.endpoint);
    let channel = build_channel(&args.endpoint).await
        .map_err(|e| anyhow::anyhow!("connection failed: {e}\n\nIs the server running? Try: cargo run --bin aegis-infer -- --mock"))?;
    println!("OK");

    // ── Health check ──────────────────────────────────────────────────────────
    let mut client = AegisInferClient::new(channel.clone());
    let health = client.health(HealthRequest {}).await?.into_inner();
    println!("Health: ok={} mode={} workers={} max_batch={} delay_ms={}",
        health.ok, health.mode, health.workers, health.max_batch, health.delay_ms);

    // ── Build payloads ────────────────────────────────────────────────────────
    let total    = args.warmup + args.requests;
    let payloads = Arc::new(sample_requests(&args.payload, total));

    // ── Warm-up ───────────────────────────────────────────────────────────────
    if args.warmup > 0 {
        print!("\nWarm-up ({} requests) … ", args.warmup);
        let _ = run_batch(
            channel.clone(), Arc::clone(&payloads), 0, args.warmup,
            args.concurrency, args.print_every, false,
        ).await;
        println!("done");
    }

    // ── Benchmark ─────────────────────────────────────────────────────────────
    println!("\nBenchmarking {} requests (concurrency={}) …\n", args.requests, args.concurrency);
    let start = Instant::now();
    let timings = run_batch(
        channel.clone(),
        Arc::clone(&payloads),
        args.warmup,
        args.requests,
        args.concurrency,
        args.print_every,
        true,
    ).await;
    let elapsed = start.elapsed();

    // ── Final stats RPC ───────────────────────────────────────────────────────
    let srv_stats = client.stats(StatsRequest {}).await?.into_inner();

    // ── Report ────────────────────────────────────────────────────────────────
    let mut sorted = timings.clone();
    sorted.sort_by(|a, b| a.partial_cmp(b).unwrap());

    let rps       = args.requests as f64 / elapsed.as_secs_f64();
    let mean_ms   = sorted.iter().sum::<f64>() / sorted.len().max(1) as f64;
    let p50_ms    = percentile(&sorted, 50.0);
    let p95_ms    = percentile(&sorted, 95.0);
    let p99_ms    = percentile(&sorted, 99.0);
    let p999_ms   = percentile(&sorted, 99.9);
    let min_ms    = sorted.first().copied().unwrap_or(0.0);
    let max_ms    = sorted.last().copied().unwrap_or(0.0);
    let errors    = args.requests - sorted.len();

    println!("\n╔══════════════════════════════════════════════════════╗");
    println!("║                  Benchmark Results                   ║");
    println!("╠══════════════════════════════════════════════════════╣");
    println!("║  Duration      : {:<36}  ║", format!("{:.2}s", elapsed.as_secs_f64()));
    println!("║  Throughput    : {:<36}  ║", format!("{:.0} RPS", rps));
    println!("║  Successful    : {:<36}  ║", args.requests - errors);
    println!("║  Errors        : {:<36}  ║", errors);
    println!("╠══════════════════════════════════════════════════════╣");
    println!("║  Latency (end-to-end, ms)                            ║");
    println!("║    min         : {:<36}  ║", format!("{:.2}", min_ms));
    println!("║    mean        : {:<36}  ║", format!("{:.2}", mean_ms));
    println!("║    p50         : {:<36}  ║", format!("{:.2}", p50_ms));
    println!("║    p95         : {:<36}  ║", format!("{:.2}", p95_ms));
    println!("║    p99         : {:<36}  ║", format!("{:.2}", p99_ms));
    println!("║    p99.9       : {:<36}  ║", format!("{:.2}", p999_ms));
    println!("║    max         : {:<36}  ║", format!("{:.2}", max_ms));
    println!("╠══════════════════════════════════════════════════════╣");
    println!("║  Server-side batch stats                             ║");
    println!("║    total_req   : {:<36}  ║", srv_stats.total_requests);
    println!("║    total_batch : {:<36}  ║", srv_stats.total_batches);
    println!("║    avg_batch   : {:<36}  ║", format!("{:.1}", srv_stats.avg_batch_size));
    println!("║    max_batch   : {:<36}  ║", srv_stats.max_batch_seen);
    println!("║    avg_infer   : {:<36}  ║", format!("{:.0}µs", srv_stats.avg_infer_us));
    println!("║    attacks     : {:<36}  ║", srv_stats.total_attacks);
    println!("╚══════════════════════════════════════════════════════╝");

    Ok(())
}

// ── Concurrent request runner ─────────────────────────────────────────────────

async fn run_batch(
    channel:     Channel,
    payloads:    Arc<Vec<String>>,
    offset:      usize,
    count:       usize,
    concurrency: usize,
    print_every: usize,
    verbose:     bool,
) -> Vec<f64> {
    let sem       = Arc::new(tokio::sync::Semaphore::new(concurrency));
    let mut set   = JoinSet::new();
    let completed = Arc::new(std::sync::atomic::AtomicUsize::new(0));

    for i in 0..count {
        let permit  = sem.clone().acquire_owned().await.unwrap();
        let ch      = channel.clone();
        let payload = payloads[offset + i].clone();
        let done    = Arc::clone(&completed);
        let pe      = print_every;
        let verb    = verbose;

        set.spawn(async move {
            let mut client = AegisInferClient::new(ch);
            let req = ClassifyRequest {
                request_id:  format!("bench-{i}"),
                features:    vec![],
                raw_request: payload,
            };

            let t0 = Instant::now();
            let result = client
                .classify(req)
                .await;
            let ms = t0.elapsed().as_secs_f64() * 1000.0;

            drop(permit);

            let n = done.fetch_add(1, std::sync::atomic::Ordering::Relaxed) + 1;
            if verb && pe > 0 && n % pe == 0 {
                println!("  … {n} requests done");
            }

            result.ok().map(|r| {
                let inner = r.into_inner();
                (ms, inner.batch_size)
            })
        });
    }

    let mut timings    = Vec::with_capacity(count);
    let mut batch_seen = Vec::with_capacity(count);

    while let Some(res) = set.join_next().await {
        if let Ok(Some((ms, bs))) = res {
            timings.push(ms);
            batch_seen.push(bs);
        }
    }

    if verbose && !batch_seen.is_empty() {
        let sum: u32 = batch_seen.iter().sum();
        let avg = sum as f64 / batch_seen.len() as f64;
        let max = batch_seen.iter().max().copied().unwrap_or(0);
        println!("  client-observed batch: avg={:.1} max={}", avg, max);
    }

    timings
}
